import java.util.concurrent.atomic.AtomicLong;
public class ParallelSum {static long shared;static void addRange(int[] a,int from,int to){for(int i=from;i<to;i++)shared+=a[i];}public static void main(String[] args)throws Exception{int[] a=new int[100000];java.util.Arrays.fill(a,1);Thread[] t=new Thread[4];shared=0;for(int k=0;k<4;k++){final int start=k*a.length/4,end=(k+1)*a.length/4;t[k]=new Thread(()->addRange(a,start,end));t[k].start();}for(Thread x:t)x.join();System.out.println("Unsynchronized: "+shared);long start=System.nanoTime();shared=0;for(int k=0;k<4;k++){final int s=k*a.length/4,e=(k+1)*a.length/4;t[k]=new Thread(()->{long local=0;for(int i=s;i<e;i++)local+=a[i];synchronized(ParallelSum.class){shared+=local;}});t[k].start();}for(Thread x:t)x.join();System.out.println("Synchronized merge: "+shared+", time ns: "+(System.nanoTime()-start));AtomicLong atomic=new AtomicLong();start=System.nanoTime();for(int k=0;k<4;k++){final int s=k*a.length/4,e=(k+1)*a.length/4;t[k]=new Thread(()->{long local=0;for(int i=s;i<e;i++)local+=a[i];atomic.addAndGet(local);});t[k].start();}for(Thread x:t)x.join();System.out.println("AtomicLong: "+atomic.get()+", time ns: "+(System.nanoTime()-start));}}
